; nokeys.asm -- chapter 17: mode 2, and then CHGET
; generated by gen17.py
        INCLUDE "msx.inc"
        OUTPUT "nokeys.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
ticks   EQU RESULTS             ; frames the program's routine counted
key     EQU RESULTS + 2         ; what CHGET gave
; Mode 2 and a routine of the program's own; then CHGET, which waits for the
; key that the BIOS's routine would have read.
init:   di
        ld sp, SYS_AREA
        ld hl, 0
        ld (ticks), hl
        ld a, $FF
        ld (key), a
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
k1:     call CHGET              ; a key, through the BIOS
k2:     ld (key), a
stop:   jr stop

; isr: counts the frames
isr:    push af
        push hl
        in a, (VDP_CTRL)        ; the status: the VDP takes its signal down
        ld hl, (ticks)
        inc hl
        ld (ticks), hl
        pop hl
        pop af
        ei
        ret
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
